ALTER TABLE "InventoryTransaction" ADD COLUMN "sparePartId" UUID;
CREATE TABLE "PurchaseRequest" ("id" UUID PRIMARY KEY,"number" TEXT NOT NULL UNIQUE,"requestDate" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"department" TEXT NOT NULL,"requesterId" UUID NOT NULL,"requesterName" TEXT NOT NULL,"requiredDate" TIMESTAMP(3) NOT NULL,"priority" TEXT NOT NULL DEFAULT 'NORMAL',"status" TEXT NOT NULL DEFAULT 'DRAFT',"reason" TEXT NOT NULL,"notes" TEXT,"estimatedTotal" DECIMAL(18,2) NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "PurchaseRequestItem" ("id" UUID PRIMARY KEY,"purchaseRequestId" UUID NOT NULL,"sparePartId" UUID,"description" TEXT NOT NULL,"category" TEXT NOT NULL,"quantity" DECIMAL(18,3) NOT NULL,"unit" TEXT NOT NULL,"estimatedPrice" DECIMAL(18,2) NOT NULL,"reason" TEXT NOT NULL);
CREATE TABLE "PurchaseOrder" ("id" UUID PRIMARY KEY,"number" TEXT NOT NULL UNIQUE,"purchaseRequestId" UUID,"supplierId" UUID NOT NULL,"orderDate" TIMESTAMP(3) NOT NULL,"expectedDate" TIMESTAMP(3) NOT NULL,"status" TEXT NOT NULL DEFAULT 'DRAFT',"subtotal" DECIMAL(18,2) NOT NULL,"tax" DECIMAL(18,2) NOT NULL DEFAULT 0,"total" DECIMAL(18,2) NOT NULL,"notes" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "PurchaseOrderItem" ("id" UUID PRIMARY KEY,"purchaseOrderId" UUID NOT NULL,"purchaseRequestItemId" UUID,"sparePartId" UUID,"description" TEXT NOT NULL,"category" TEXT NOT NULL,"quantity" DECIMAL(18,3) NOT NULL,"receivedQuantity" DECIMAL(18,3) NOT NULL DEFAULT 0,"unit" TEXT NOT NULL,"unitPrice" DECIMAL(18,2) NOT NULL);
CREATE TABLE "Receiving" ("id" UUID PRIMARY KEY,"number" TEXT NOT NULL UNIQUE,"purchaseOrderId" UUID NOT NULL,"receivingDate" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"deliveryNote" TEXT,"receivedById" UUID NOT NULL,"receivedByName" TEXT NOT NULL,"notes" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "ReceivingItem" ("id" UUID PRIMARY KEY,"receivingId" UUID NOT NULL,"purchaseOrderItemId" UUID NOT NULL,"stockpileId" UUID NOT NULL,"quantity" DECIMAL(18,3) NOT NULL);
CREATE TABLE "Equipment" ("id" UUID PRIMARY KEY,"code" TEXT NOT NULL UNIQUE,"name" TEXT NOT NULL,"category" TEXT NOT NULL,"brand" TEXT,"model" TEXT,"serialNumber" TEXT UNIQUE,"installationDate" TIMESTAMP(3),"location" TEXT NOT NULL,"hourMeter" DECIMAL(12,2) NOT NULL DEFAULT 0,"maintenanceInterval" DECIMAL(12,2) NOT NULL DEFAULT 250,"lastMaintenanceHour" DECIMAL(12,2) NOT NULL DEFAULT 0,"status" TEXT NOT NULL DEFAULT 'OPERATIONAL',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "SparePart" ("id" UUID PRIMARY KEY,"code" TEXT NOT NULL UNIQUE,"name" TEXT NOT NULL,"category" TEXT NOT NULL,"manufacturer" TEXT,"partNumber" TEXT,"unit" TEXT NOT NULL DEFAULT 'PCS',"minimumStock" DECIMAL(18,3) NOT NULL DEFAULT 0,"unitCost" DECIMAL(18,2) NOT NULL DEFAULT 0,"supplierId" UUID,"storageLocation" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'ACTIVE',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "SparePartEquipment" ("sparePartId" UUID NOT NULL,"equipmentId" UUID NOT NULL,PRIMARY KEY("sparePartId","equipmentId"));
CREATE TABLE "Maintenance" ("id" UUID PRIMARY KEY,"number" TEXT NOT NULL UNIQUE,"equipmentId" UUID NOT NULL,"type" TEXT NOT NULL,"priority" TEXT NOT NULL DEFAULT 'NORMAL',"status" TEXT NOT NULL DEFAULT 'SCHEDULED',"problem" TEXT NOT NULL,"technician" TEXT,"scheduledAt" TIMESTAMP(3) NOT NULL,"startedAt" TIMESTAMP(3),"completedAt" TIMESTAMP(3),"interruptionStartedAt" TIMESTAMP(3),"hourMeter" DECIMAL(12,2),"laborCost" DECIMAL(18,2) NOT NULL DEFAULT 0,"externalCost" DECIMAL(18,2) NOT NULL DEFAULT 0,"otherCost" DECIMAL(18,2) NOT NULL DEFAULT 0,"rootCause" TEXT,"correctiveAction" TEXT,"notes" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "MaintenanceTask" ("id" UUID PRIMARY KEY,"maintenanceId" UUID NOT NULL,"description" TEXT NOT NULL,"required" BOOLEAN NOT NULL DEFAULT true,"completedAt" TIMESTAMP(3),"completedBy" TEXT,"sortOrder" INTEGER NOT NULL DEFAULT 0);
CREATE TABLE "MaintenanceSparePart" ("id" UUID PRIMARY KEY,"maintenanceId" UUID NOT NULL,"sparePartId" UUID NOT NULL,"stockpileId" UUID NOT NULL,"quantity" DECIMAL(18,3) NOT NULL,"unitCost" DECIMAL(18,2) NOT NULL);
ALTER TABLE "PurchaseRequestItem" ADD CONSTRAINT "PurchaseRequestItem_purchaseRequestId_fkey" FOREIGN KEY("purchaseRequestId") REFERENCES "PurchaseRequest"("id") ON DELETE CASCADE; ALTER TABLE "PurchaseRequestItem" ADD CONSTRAINT "PurchaseRequestItem_sparePartId_fkey" FOREIGN KEY("sparePartId") REFERENCES "SparePart"("id");
ALTER TABLE "PurchaseOrder" ADD CONSTRAINT "PurchaseOrder_purchaseRequestId_fkey" FOREIGN KEY("purchaseRequestId") REFERENCES "PurchaseRequest"("id"); ALTER TABLE "PurchaseOrder" ADD CONSTRAINT "PurchaseOrder_supplierId_fkey" FOREIGN KEY("supplierId") REFERENCES "Supplier"("id");
ALTER TABLE "PurchaseOrderItem" ADD CONSTRAINT "PurchaseOrderItem_purchaseOrderId_fkey" FOREIGN KEY("purchaseOrderId") REFERENCES "PurchaseOrder"("id") ON DELETE CASCADE; ALTER TABLE "PurchaseOrderItem" ADD CONSTRAINT "PurchaseOrderItem_purchaseRequestItemId_fkey" FOREIGN KEY("purchaseRequestItemId") REFERENCES "PurchaseRequestItem"("id"); ALTER TABLE "PurchaseOrderItem" ADD CONSTRAINT "PurchaseOrderItem_sparePartId_fkey" FOREIGN KEY("sparePartId") REFERENCES "SparePart"("id");
ALTER TABLE "Receiving" ADD CONSTRAINT "Receiving_purchaseOrderId_fkey" FOREIGN KEY("purchaseOrderId") REFERENCES "PurchaseOrder"("id"); ALTER TABLE "ReceivingItem" ADD CONSTRAINT "ReceivingItem_receivingId_fkey" FOREIGN KEY("receivingId") REFERENCES "Receiving"("id") ON DELETE CASCADE; ALTER TABLE "ReceivingItem" ADD CONSTRAINT "ReceivingItem_purchaseOrderItemId_fkey" FOREIGN KEY("purchaseOrderItemId") REFERENCES "PurchaseOrderItem"("id"); ALTER TABLE "ReceivingItem" ADD CONSTRAINT "ReceivingItem_stockpileId_fkey" FOREIGN KEY("stockpileId") REFERENCES "Stockpile"("id");
ALTER TABLE "SparePart" ADD CONSTRAINT "SparePart_supplierId_fkey" FOREIGN KEY("supplierId") REFERENCES "Supplier"("id"); ALTER TABLE "SparePartEquipment" ADD CONSTRAINT "SparePartEquipment_sparePartId_fkey" FOREIGN KEY("sparePartId") REFERENCES "SparePart"("id") ON DELETE CASCADE; ALTER TABLE "SparePartEquipment" ADD CONSTRAINT "SparePartEquipment_equipmentId_fkey" FOREIGN KEY("equipmentId") REFERENCES "Equipment"("id") ON DELETE CASCADE;
ALTER TABLE "Maintenance" ADD CONSTRAINT "Maintenance_equipmentId_fkey" FOREIGN KEY("equipmentId") REFERENCES "Equipment"("id"); ALTER TABLE "MaintenanceTask" ADD CONSTRAINT "MaintenanceTask_maintenanceId_fkey" FOREIGN KEY("maintenanceId") REFERENCES "Maintenance"("id") ON DELETE CASCADE; ALTER TABLE "MaintenanceSparePart" ADD CONSTRAINT "MaintenanceSparePart_maintenanceId_fkey" FOREIGN KEY("maintenanceId") REFERENCES "Maintenance"("id") ON DELETE CASCADE; ALTER TABLE "MaintenanceSparePart" ADD CONSTRAINT "MaintenanceSparePart_sparePartId_fkey" FOREIGN KEY("sparePartId") REFERENCES "SparePart"("id"); ALTER TABLE "InventoryTransaction" ADD CONSTRAINT "InventoryTransaction_sparePartId_fkey" FOREIGN KEY("sparePartId") REFERENCES "SparePart"("id");
CREATE INDEX "PurchaseRequest_status_department_requestDate_idx" ON "PurchaseRequest"("status","department","requestDate"); CREATE INDEX "PurchaseOrder_status_supplierId_expectedDate_idx" ON "PurchaseOrder"("status","supplierId","expectedDate"); CREATE INDEX "Equipment_category_status_location_idx" ON "Equipment"("category","status","location"); CREATE INDEX "Maintenance_status_scheduledAt_equipmentId_idx" ON "Maintenance"("status","scheduledAt","equipmentId"); CREATE INDEX "MaintenanceSparePart_maintenanceId_sparePartId_idx" ON "MaintenanceSparePart"("maintenanceId","sparePartId");
